def similar_elements(list1, list2):
    """
    Find similar elements shared between two lists.

    Returns a tuple of elements that are common to both input lists.
    """
    return tuple(set(list1) & set(list2))

def is_not_prime(n):
    """
    Returns True if n is NOT a prime number, False if n is prime.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def remove_Occ(s, ch):
    """
    Remove the first and last occurrence of a character `ch` from the string `s`.
    """
    s = list(s)
    first_index = None
    last_index = None

    for i in range(len(s)):
        if s[i] == ch:
            first_index = i
            break

    for i in range(len(s) - 1, -1, -1):
        if s[i] == ch:
            last_index = i
            break

    if first_index is None:
        return "".join(s)

    if first_index == last_index:
        del s[first_index]
    else:
        # Remove the later index first to avoid shifting
        del s[last_index]
        del s[first_index]

    return "".join(s)

import re

def text_lowercase_underscore(text):
    pattern = r'^[a-z]+_[a-z]+$'
    if re.search(pattern, text):
        return 'Found a match!'
    else:
        return 'Not matched!'

def check(n):
    rev = int(str(n)[::-1])
    return n == 2 * rev - 1

def smallest_num(nums):
    """
    Find the smallest number in a list.

    Returns None if the list is empty.
    """
    if not nums:
        return None
    return min(nums)

def recursive_list_sum(lst):
    """
    Recursively sum elements in a list, including nested lists.
    """
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def pos_count(lst):
    """
    Count the number of positive integers in a list.
    Zero and negative numbers are not counted.
    """
    return sum(1 for x in lst if x > 0)

def get_equal(Input, k):
    """
    Check if all tuples in the given list have length equal to k.

    :param Input: list of tuples
    :param k: expected length to check against
    :return: "Equal" if all tuples have length k, otherwise "Not Equal"
    """
    flag = 1
    for tup in Input:
        if len(tup) != k:
            flag = 0
            break
    if flag == 1:
        return "Equal"
    else:
        return "Not Equal"
